#include <map>
#include <string>

int main() {
    std::map<std::string, float> coll = {
        {"old_key", 10.0f}
    };

    auto pos = coll.begin();

    // 1. Changing the mapped value is OK
    pos->second = 13.5f; // Compiles and modifies value

    // 2. Changing the key is a compile-time ERROR
    // pos->first = "new_key"; 
    // Error: assignment of read-only member 'std::pair<const Key, T>::first'
}
